(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["aussie"] = {"ui":{"skip":"Skip to the good bit","back":"← Back to AI-gile","lang.button":"Language: {name}","lang.dialog":"Pick a language, mate","lang.search":"Search languages","lang.none":"No language matches that","lang.notYet":"{name} hasn't been translated yet","theme.aria":"Switch theme: light, dark or black","theme.toLight":"Switch to light theme","theme.toDark":"Switch to dark theme","theme.toBlack":"Switch to black theme (true black, easy on OLED screens)","words.underline":"Underline these words on the page","words.underlineHelp":"Hover or tap a dotted word to see what it means. Easy.","words.col.todo":"Cards picked for now: the team's gonna smash these out next.","words.col.doing":"An AI's workin' on this card right now.","words.col.review":"One AI's done the work; another gives it a once-over before it gets to ya.","words.col.verify":"Waitin' on you: give it a go and tell us if it works.","words.col.team":"Your notes or answers, waitin' for the team to grab 'em.","words.col.done":"Finished and signed off, mate.","index.title":"AI-gile: your AI dev team, on one board","index.description":"AI-gile is a kanban board for AI coding teams. They work while you're having a snooze; you get one short pile of things to decide, test and accept.","hero.logoAlt":"AI-gile board icon","hero.h1.html":"Your AI dev team, on one&nbsp;board.","hero.alpha":"🐣 Closed pre-alpha","hero.alphaTitle":"Early and a bit rough: ta for giving it a go!","hero.lede":"They build while you sleep. You wake up to one short pile: a few questions, a few things to test, a purple diamond or two. Click, accept, back to your cuppa.","dl.windows":"Windows app","dl.browser":"Run it in your browser","dl.messenger":"📱 Messenger for your mobile","dl.soon":"Coming soon","dl.notify":"🔔 Give me a yell when it opens","dl.notifySmall":"Alpha or beta","hero.secondary":"Agile, but the team never needs a stand-up coffee. (They do stand-ups anyway, the keen beans.)","pitch.h2":"AI-gile in as many words as you reckon","pitch.lede":"Pick a length, from one word to 144. Each length is its own description, written for that size. Drag the slider or use the arrow keys.","pitch.rangeLabel":"Length in words","pitch.dice":"🎲 another go","pitch.words.one":"{n} word","pitch.words.other":"{n} words","pitch.letters.one":"{n} letter","pitch.letters.other":"{n} letters","pitch.chars.one":"{n} character","pitch.chars.other":"{n} characters","count.line.html.one":"{n} card on the board right now","count.line.html.other":"{n} cards on the board right now","people.humans.html.one":"👥 {n} human","people.humans.html.other":"👥 {n} humans","people.agents.html.one":"🤖 {n} agent","people.agents.html.other":"🤖 {n} agents","people.working.html.one":"⚡ {n} flat out right now","people.working.html.other":"⚡ {n} flat out right now","pre.title":"AI-gile: something's bein' built","pre.description":"Something's bein' built here. A board where AI teams build what you ask for, and teach you as they go. Closed pre-alpha with mates for now.","pre.h1":"Something's bein' built here. 🤫","pre.line":"A board where AI teams build what you ask for, and teach you as they go. Closed pre-alpha with mates for now.","pre.btn":"🔔 Give me a yell when it opens","pre.peek":"Behind the glass: the real board, live. Every card's a coloured bar.","pre.peekFake":"Behind the glass: what a board looks like when it's flat out.","pre.night":"🌙 The night watchman's runnin' the show · 😴 the human's havin' a kip","features.aria":"What it does","f.pile.h":"One pile for you","f.pile.html":"<b>For you</b> holds everything waiting on you, across every project: questions, things to test, jobs only a human can do. Your queue says what's next and how long it'll take.","f.sleep.h":"Teams that work while you sleep","f.sleep.p":"Each project has a lead and a team of AI agents. Comment on a card and the team wakes up, does the work, and hands it back with steps a knackered human can follow.","f.tester.h":"An AI tester checks first","f.tester.p":"Before anything reaches you, a tester follows the steps in a copy of the app and shows what it saw, with a screenshot. Flick through the ones that passed and accept in a click.","f.proof.h":"Proof, not promises","f.proof.p":"Every hand-over shows what changed: the files, the diff, the screenshots. No opening every app to see if it's done.","f.chat.h":"Chat with your leads","f.chat.p":"A Discord-style rail: one icon per project, purple diamonds for what needs you. Message a lead an idea; they turn it into cards and a plan, with a ✅ Go button.","f.tidy.h":"Keeps itself tidy","f.tidy.p":"Related cards fold into one, muddled titles get fixed, and a token check keeps the code lean. Fewer things to juggle, less to think about.","f.private.h":"Yours, on your computer","f.private.li1":"The board runs on your own machine and only answers to you.","f.private.li2":"Private DMs between mates are end-to-end encrypted.","f.private.li3":"No accounts, no trackers, no cookies.","f.lang.h":"In your language","f.lang.p":"Over 120 languages, from Dutch, Welsh and Japanese to pirate, Yoda and Klingon, with a quick switch back to English for the industry jargon.","f.service.h":"From an idea to a real service","f.service.p":"Built something with AI that people actually use now? Mark it as a service and the board helps you run it properly: uptime checks, a public status page, incidents with a write-up, changes that need a Go, backups checked every day. Help shows you each step as you go.","msgr.h2":"AI-gile Messenger: your team in your pocket","msgr.p1":"Have a yarn with your AI team without opening the board. Chat with your project leads and your mates, and check a card's test steps and answer them, all from your mobile.","msgr.p2":"To pair it, scan a QR code on your board. First time? A friendly demo chat shows you the ropes.","msgr.when":"Android first, then a web version for mobiles and iPhone.","msgr.who":"Your project lead","msgr.b1":"The dark mode fix is good to go. Want the test steps?","msgr.b2":"Yes please, legend!","msgr.b3":"1. Open Settings. 2. Pick Dark. Look right to you?","tl.aria":"Timeline from the first yarn to the roadmap","tl.h2":"From the first yarn to what's next","tl.lede":"Real dates and times, in your own time zone. After today it's the plan, with no dates promised.","tl.today":"Today","tl.planned":"planned","tl.doing":"in progress","tl.cards.one":"{n} card","tl.cards.other":"{n} cards","join.h2":"Jump in","join.lede":"AI-gile is being built by a bearded weirdo with AuDHD and a few mental health battles, plus heaps of patient agents. It's private for now, in a closed alpha with mates. Keen for a go when it opens up?","join.btn":"Register interest","join.small":"We'll email you, nothing else","footer.tag":"AI-gile. No trackers, no cookies, no stand-up coffee.","footer.licence":"Business licence","footer.status":"Status","footer.privacy":"What we keep","footer.thanks":"Calls thanks to ChilledChat","form.sending":"Sending…","form.failed":"That didn't work: have another go later.","form.offline":"Couldn't reach AI-gile: have another go later.","form.keep":"We only use this to get back to you, then we bin it. No trackers, no cookies.","form.keepLink":"What we keep","interest.title":"AI-gile: give me a yell when the alpha opens","interest.description":"Leave your email to hear when AI-gile's closed alpha or beta opens.","interest.h1":"🔔 Give me a yell when it opens","interest.lede":"AI-gile is in closed pre-alpha. Leave your email and we'll write once, when there's a spot for you.","interest.email":"Your email","interest.which":"Which test?","interest.alpha":"Closed alpha: early, rough, heaps of changes","interest.beta":"Beta: steadier, later","interest.both":"Either, whichever comes first","interest.submit":"Pop me on the list","interest.thanks":"Ta! You're on the list.","licence.title":"AI-gile: business licence","licence.description":"Using AI-gile in your business? Apply for a free business licence.","licence.h1":"📜 Business licence","licence.lede":"Using AI-gile at work? Tell us who you are and what you do. If it does some good, the licence is free.","licence.company":"Company","licence.website":"Website","licence.what":"What you do","licence.how":"How it helps the world","licence.email":"Email","licence.submit":"Apply","licence.thanks":"Ta! We'll reply by email.","status.title":"AI-gile status","status.h1":"AI-gile status","status.quiet":"All quiet, no worries","status.intro":"Is AI-gile going alright right now? This page checks the website, board sharing, calls and the download every 5 minutes.","status.up":"Going fine (answered in {ms} ms)","status.slow":"Didn't answer the last check, having another go","status.down":"Cactus: didn't answer the last two checks","status.svc.web":"Website","status.svc.web.offers":"This site: what AI-gile is, and the interest form","status.svc.boards":"Board sharing","status.svc.boards.offers":"Public boards, messages between mates and invites","status.svc.calls":"Calls","status.svc.calls.offers":"Voice, video and screen share in AI-gile","status.svc.download":"Download","status.svc.download.offers":"The Windows installer and invite links","status.checking":"Having a look…","status.offline":"Can't reach the status service right now (trying again)","status.updated":"updated {ago}","status.justNow":"just now","status.min":"{n} min ago","status.hours":"{n} h ago","status.days":"{n} d ago","privacy.title":"AI-gile: what we keep","privacy.h1":"What we keep","privacy.lede":"Short version: only what you send us, and not for long.","privacy.only":"Only what you send us: what you type into a form, like your email. Nothing else about you, fair dinkum.","privacy.sealed":"It's sealed up so our server can't read it: in your browser before it heads off (on an older browser, the second it lands). Only our own board can open it.","privacy.server":"It's deleted off the server as soon as it reaches our board. Anything still hanging round after 30 days gets binned anyway.","privacy.board":"We keep it on our board only till we've got back to you, then we bin it there too.","privacy.none":"No trackers, no cookies, no analytics. Too easy.","privacy.local":"Your language and light or dark pick stay in your own browser. They never get sent to us.","privacy.ask":"Want it gone sooner? Reply to our email and give us a yell.","live.h2":"Watch it bein' built, live, mate","live.caption":"Every card's hidden: ya see the shape of the work, not the words.","live.watching.one":"live: {n} watchin'","live.watching.other":"live: {n} watchin'","live.last.now":"Last card moved just now","live.last.min.one":"Last card moved {n} min ago","live.last.min.other":"Last card moved {n} min ago","live.last.hour.one":"Last card moved {n} hour ago","live.last.hour.other":"Last card moved {n} hours ago","live.last.day.one":"Last card moved {n} day ago","live.last.day.other":"Last card moved {n} days ago","live.offline":"The live board's havin' a bit of a breather, mate. Check back soon.","live.cols":"Backlog|To do|In progress|Team checking|For you to test|For the team|Done"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Robots.","Sorted."]},{"n":2,"texts":["Robot kanban.","Agents, sorted.","Ideas, built."]},{"n":3,"texts":["Kanban for robots.","Ideas become features.","Free agent kanban."]},{"n":5,"texts":["Kanban board run by agents.","You write cards. Agents build.","Free, local, tested, a bit daft."]},{"n":8,"texts":["Free kanban board where AI agents do the yakka.","Write an idea. Agents build it. You say righto.","Agile for one human and heaps of patient robots."]},{"n":13,"texts":["A kanban board on your own computer where AI agents grab the cards.","Write an idea. A team of agents builds it. A tester gives it a once-over.","Free, no accounts, no trackers: a board, some robots, and you running the show."]},{"n":21,"texts":["AI-gile is a kanban board for working with AI coding agents. They grab the cards; you test them and say yes.","Each project gets a lead and a team of AI agents. Comment on any card and the team gets stuck in.","A free, personal to-do board that runs on your own computer. The workers are robots. The one saying yes is you."]},{"n":34,"texts":["You put ideas on a board. A team of AI agents turns them into working features, tests them, and hands them back with steps to try. Nothing counts as done until you give the nod.","AI-gile is a homemade kanban board that Rich built with a fair bit of help from the agents it now looks after. It's free, runs on your computer, and gets shared with mates, not sold.","Picture a normal kanban board, with columns from Backlog to Done, except the cards get picked up by AI agents. They report progress, sing out when they're stuck, and always wait for your thumbs up."]},{"n":55,"texts":["AI-gile is a kanban board where the team is made of AI agents. Each project has a lead who plans the work and helpers who build it. When a feature's ready, an AI tester has a go and takes a screenshot, then it lands in your pile. Accept it, or comment and they do it over.","It started as one bloke's way of keeping track of heaps of AI coding sessions at once, and grew into a proper board. It runs on your machine, needs no account, and has no trackers. It's free for mates and anyone curious. It's also unfinished, so expect a few rough edges and the odd surprise.","Here's the honest version. You still need to come up with the ideas, and you still need to check the results. What AI-gile does is everything in between: it keeps the cards in order, wakes the right agent when you comment, shows exactly what changed, and keeps the lot in one short pile for you."]},{"n":89,"texts":["AI-gile is a free kanban board that you run on your own computer. Instead of people, each project has a team of AI agents: a lead who turns your ideas into cards and a plan, and helpers who pick the cards up in priority order. When something's built, an AI tester follows the test steps and shows you what it saw. Then it waits in one pile marked For you. You accept it, or you comment and the team has another crack. Nothing ever gets to Done without you.","A few features you mightn't expect. A night watch keeps the To do column topped up while you're asleep, picking cards that don't need an answer from you. A token counter shows how much the agents have used today and this week, and No Token Mode tells them to stop spending. You can message your mates, and private messages are end-to-end encrypted. The board speaks about 120 languages, including Dutch, Flemish, pirate and Klingon. None of it costs a cent, and nobody's trying to flog it to you either.","AI-gile is a small, personal project, not a company. Rich wanted to look after a few AI coding projects without opening every app to check on them, so he and the agents built a board for it, then used the board to build the rest of itself. It's in closed pre-alpha, which means it works, mostly, for a handful of mates. There's no pricing page, no newsletter and no growth plan. If it sounds handy, you can ask for a go when it opens up a bit more."]},{"n":144,"texts":["AI-gile is a kanban board for one human and a heap of AI agents. It runs on your own computer and it's completely free. You add projects, and each project gets a lead and a small team. You chat with the lead, a bit like Discord, and describe an idea; the lead turns it into cards and a plan, then waits for you to press Go. The team works through the cards in priority order, using a simple command line made for language models. Before anything comes back to you, an AI tester follows the steps in a copy of the app and attaches a screenshot. Finished work lands in your pile with the changed files and the diff. You accept it, or you leave a comment and the team wakes up and has another go. Only you can move a card to Done.","A day with AI-gile, roughly. In the evening you leave a few comments: this button's in the wrong spot, that list should be sorted, could we have a dark mode. You go to bed. The agents read the comments, make the changes, test them and hand them back to you. If To do runs dry, the night watch tops it up from the backlog with cards that need no answer from you. In the morning there's one short pile: a couple of questions and a few things to try, each with steps a sleepy person can follow and a screenshot of it working. You click through, accept the good ones and send back the rest. A token counter shows what it all used, and No Token Mode is there for lean weeks. Then you have brekkie, which the agents can't help with yet.","First, what AI-gile isn't. It isn't a startup, it isn't for sale, and nobody's collecting your data. It's a free board that runs on your computer, with no accounts, no trackers and no cookies. What it is: one tidy place to see every AI coding project at once, with a team of agents doing the cards and you making the decisions. It folds related cards together, fixes muddled titles, and keeps an eye on how lean the code stays. It speaks about 120 languages, from Dutch and Flemish to pirate and Klingon. Mates can message each other, privately and encrypted. It was built by Rich and a whole lot of patient agents, mostly using itself. It's in closed pre-alpha, so it's rough in spots. If it sounds like fun, ask nicely and you might get in early."]}],"quips":{"1":"One word. Bold. Maybe a bit too bold.","3":"Three words. Already more honest than most product pages.","8":"Eight words. Still shorter than a stand-up.","21":"The lengths are story points, by the way. Course they are.","55":"Fifty-five words. Two cards got finished while you read that.","144":"That's the long one. There's no 233. The agents have knocked off for the arvo."}},"timeline":{"first-idea.name":"The first idea","first-idea.line":"The very first yarn, before there was a single line of code.","first-board.name":"First board","first-board.line":"A board that tracks its own build: cards, columns, drag and drop, projects.","team-roles.name":"Team and roles","team-roles.line":"Agent profiles, team templates, spaces and who does what.","install.name":"Install and releases","install.line":"A zip a mate can install, self-updates, channels and rolling back.","usage-saver.name":"Usage saver","usage-saver.line":"Measure what runs cost, keep the code lean, make your limit last.","friends.name":"Mates and sharing","friends.line":"Private DMs, a scrambled relay, invites, roles and shared projects.","languages.name":"Languages","languages.line":"Every screen text in a language file, with Dutch and Flemish first off the rank.","ai-tester.name":"AI tester","ai-tester.line":"A tester checks every hand-over first and shows what it saw.","website.name":"The website","website.line":"aigile.lol, the teaser and this timeline.","streaming.name":"Chat and streaming","streaming.line":"Discord, Twitch, OBS, streamer mode, GIFs and emojis.","no-ai.name":"No AI edition","no-ai.line":"A board for folks who code without AI, and public boards.","night-watch.name":"Night watch","night-watch.line":"A watchman and Scrum Master keep the teams on task while you're off in dreamland.","p-more.name":"Everything else","p-more.line":"Smaller ideas still waiting their turn.","p-android.name":"Phone and Android","p-android.line":"Get to your board from a phone, then a proper Android app.","p-release.name":"Alpha and beyond","p-release.line":"Closed alpha, the live site, then beta.","p-languages.name":"More languages","p-languages.line":"130 languages, plus an immersion mode for learners.","p-engines.name":"More AI engines","p-engines.line":"Pick Claude, Codex, Gemini, Copilot or Cursor for each agent.","p-pro.name":"Pro practice","p-pro.line":"Risk labels, merge gates, incident cards and guard rails.","p-self.name":"Looking after you","p-self.line":"Tired mode, self-care reminders and 4:20.","p-servers.name":"Servers and scale","p-servers.line":"Global server settings, roles and planning for growth.","p-livestream.name":"Streaming extras","p-livestream.line":"Twitch chat, custom emojis and a public live view."},"words":{"button":"📖 Industry jargon","h":"📖 Words explained","intro":"Free training in plain language: every word you meet from a first idea to a service people rely on, with Agile, building, keeping it safe and working with AI along the way.","search":"Search a word…","none":"No word matches that.","close":"Close","count":{"one":"{count} word","other":"{count} words"},"groups":[{"id":"idea","name":"💡 Ideas and discovery"},{"id":"plan","name":"🗺️ Planning the work"},{"id":"agile","name":"🔁 Agile ways of working"},{"id":"build","name":"🛠️ Building it"},{"id":"test","name":"🧪 Testing and quality"},{"id":"change","name":"🔀 Changing it safely"},{"id":"run","name":"🛎️ Running a service"},{"id":"sec","name":"🔒 Security and privacy"},{"id":"ai","name":"🤖 Working with AI"},{"id":"money","name":"💰 Money and licences"}],"list":[{"id":"discovery","g":"idea","word":"Discovery","text":"The early stage of working out which problem is worth solving and for whom, before anything gets built.","also":["discovery phase"]},{"id":"problemstmt","g":"idea","word":"Problem statement","text":"One or two sentences saying who's got a problem, what it is and why it matters, so everyone's aiming at the same target.","also":["problem statements"]},{"id":"user","g":"idea","word":"User","text":"A person who uses what you build. Their needs are what the work is for.","also":["users"],"noTip":1},{"id":"stakeholder","g":"idea","word":"Stakeholder","text":"Anyone who cares how the work turns out or is affected by it, like the people paying for it, using it or supporting it.","also":["stakeholders"]},{"id":"persona","g":"idea","word":"Persona","text":"A made-up but realistic person who stands for one kind of user, so the team can ask “would Sam find this easy?”","also":["personas"]},{"id":"userresearch","g":"idea","word":"User research","text":"Chatting to and watching real people to learn what they need, rather than guessing.","also":["user interviews"]},{"id":"journey","g":"idea","word":"User journey","text":"The steps a person takes to get something done, from first hearing about it to finishing, including the bits outside your product. Drawing it out shows where they get stuck.","also":["user journeys","customer journey"]},{"id":"painpoint","g":"idea","word":"Pain point","text":"Something that annoys people or slows them down today. Good products take the pain away.","also":["pain points"]},{"id":"assumption","g":"idea","word":"Assumption","text":"Something you reckon is true but haven't checked yet. Writing assumptions down shows what to test first.","also":["assumptions"],"noTip":1},{"id":"hypothesis","g":"idea","word":"Hypothesis","text":"A best guess you plan to check, with what you expect to happen, like “people will sign up if the first month is free”.","also":["hypotheses"]},{"id":"experiment","g":"idea","word":"Experiment","text":"A small planned test to find out whether an idea works, before you bet the farm on it.","also":["experiments"],"noTip":1},{"id":"poc","g":"idea","word":"Proof of concept (PoC)","text":"A quick rough go to see if an idea can work at all. It's usually binned once you've got your answer.","also":["PoC","proof of concept"]},{"id":"prototype","g":"idea","word":"Prototype","text":"An early model of the product, often clickable pictures, so you can try the idea on people before building it properly.","also":["prototypes"]},{"id":"wireframe","g":"idea","word":"Wireframe","text":"A simple sketch of a screen showing where things go, without colours or real content.","also":["wireframes"]},{"id":"mockup","g":"idea","word":"Mockup","text":"A detailed picture of how a screen will look, with real colours and text, but nothing works yet.","also":["mockups","mock-up","mock-ups"]},{"id":"bizcase","g":"idea","word":"Business case","text":"The reasons for doing a project: what it costs, what it brings in or saves, and the risks.","also":["business cases"]},{"id":"feasibility","g":"idea","word":"Feasibility","text":"Whether something can really be built and looked after with the time, money and skills you've got."},{"id":"outcome","g":"idea","word":"Outcome","text":"The change you want for people, like fewer missed appointments. It matters more than how much you build.","also":["outcomes"],"noTip":1},{"id":"output","g":"idea","word":"Output","text":"Something the team makes, like a new screen or a report. Making it doesn't automatically mean it helps anyone.","also":["outputs"],"noTip":1},{"id":"successmetric","g":"idea","word":"Success metric","text":"A number that tells you whether the work did what it was for, like more people finishing their order.","also":["success metrics"]},{"id":"kpi","g":"idea","word":"Key performance indicator (KPI)","text":"An important number you keep an eye on to see if things are going well, like sign-ups per week.","also":["KPI","KPIs","key performance indicator"]},{"id":"okr","g":"idea","word":"Objectives and key results (OKRs)","text":"A way of setting goals: the objective says what you want, and a few key results are the numbers that show you got there.","also":["OKR","OKRs"]},{"id":"product","g":"plan","word":"Product","text":"The thing being built and looked after for its users, such as an app, a website or a tool.","also":["products"],"noTip":1},{"id":"vision","g":"plan","word":"Product vision","text":"A short statement of who the product helps and where it's heading in the long run.","also":["vision statement"]},{"id":"po","g":"plan","word":"Product owner (PO)","text":"The person who decides what gets built and in what order, so the team always works on what matters most. In AI-gile that's you.","also":["PO","product owners"]},{"id":"pm","g":"plan","word":"Product manager (PM)","text":"The person who looks after a product's direction: which problems it solves, for whom and why. PM can also mean project manager, so check which one.","also":["product managers"]},{"id":"projmgr","g":"plan","word":"Project manager","text":"The person who keeps a project on time and on budget, tracking who does what and by when.","also":["project managers"]},{"id":"roadmap","g":"plan","word":"Roadmap","text":"A rough plan of what's coming over the next few months, in order. It shows direction, not exact dates, and changes as you learn.","also":["roadmaps"]},{"id":"milestone","g":"plan","word":"Milestone","text":"A point in a project worth marking, like “first version live” or “100 users”.","also":["milestones"]},{"id":"mvp","g":"plan","word":"Minimum viable product (MVP)","text":"The smallest version of a product that's still useful to real people, so you can learn from them early.","also":["MVP","MVPs","minimum viable product"]},{"id":"requirement","g":"plan","word":"Requirement","text":"Something the finished product must do or be.","also":["requirements"],"noTip":1},{"id":"scope","g":"plan","word":"Scope","text":"What's included in the work and, just as important, what's not.","also":["in scope","out of scope"]},{"id":"scopecreep","g":"plan","word":"Scope creep","text":"When more and more gets added to the work bit by bit, without anyone agreeing on the extra time or cost, so it never quite finishes.","also":["feature creep"]},{"id":"feature","g":"plan","word":"Feature","text":"One thing the product can do for people, like “reset your password”.","also":["features"],"noTip":1},{"id":"epic","g":"plan","word":"Epic","text":"A big piece of work, too large to do in one go, so it gets split into smaller cards.","also":["epics"]},{"id":"story","g":"plan","word":"User story","text":"A small piece of work written from the user’s side: “As a shopper, I want to save my basket, so I can finish later.” It kicks off a yarn about what to build.","also":["user stories"]},{"id":"ac","g":"plan","word":"Acceptance criteria (AC)","text":"The checks one card must pass to count as done, agreed before work starts, like “the basket is still there after I log out and back in”.","also":["acceptance criteria"]},{"id":"task","g":"plan","word":"Task","text":"A single job to be done, often one small step of a bigger story.","also":["tasks"],"noTip":1},{"id":"ticket","g":"plan","word":"Ticket","text":"Another word for a card: one piece of work or one request, tracked from start to finish.","also":["tickets"]},{"id":"priority","g":"plan","word":"Priority","text":"How important or urgent something is compared with everything else, so the most important work goes first.","also":["priorities"],"noTip":1},{"id":"prioritise","g":"plan","word":"Prioritisation","text":"Putting work in order of importance. A common way is MoSCoW: Must have, Should have, Could have, Won’t have this time.","also":["MoSCoW"]},{"id":"estimate","g":"plan","word":"Estimate","text":"A best guess at how big or how long a piece of work is. It's a guess, not a promise.","also":["estimates","estimation"],"noTip":1},{"id":"storypoints","g":"plan","word":"Story points","text":"A way of guessing the size of work by comparing cards with each other (“about twice as big as that one”) rather than in hours. They aren’t for comparing teams.","also":["story point"]},{"id":"tshirt","g":"plan","word":"T-shirt sizing","text":"Guessing the size of work as S, M, L or XL. Quick and good enough for early planning.","also":["t-shirt sizes"]},{"id":"poker","g":"plan","word":"Planning poker","text":"A game for estimating: everyone shows a size card at the same time, then the highest and lowest explain why.","also":["Scrum poker"]},{"id":"dependency","g":"plan","word":"Dependency","text":"When one piece of work can’t start or finish until another one does.","also":["dependencies"]},{"id":"blocker","g":"plan","word":"Blocker","text":"Anything stopping work from moving forward right now, like a missing answer or a busted tool.","also":["blockers"]},{"id":"deadline","g":"plan","word":"Deadline","text":"The date something has to be finished by.","also":["deadlines"],"noTip":1},{"id":"deliverable","g":"plan","word":"Deliverable","text":"Something concrete the work produces and hands over, like a working page or a report.","also":["deliverables"]},{"id":"forecast","g":"plan","word":"Forecast","text":"A prediction of what's likely to happen, like when the work will be done, based on what you know so far.","also":["forecasts"],"noTip":1},{"id":"metric","g":"plan","word":"Metric","text":"Anything you measure and track over time, like page visits or how long a fix takes.","also":["metrics"]},{"id":"feedback","g":"plan","word":"Feedback","text":"What people tell you about your work, good and bad. Getting it early and often is the heart of Agile.","noTip":1},{"id":"backlog","g":"agile","word":"Backlog","text":"The waiting list of ideas and work not planned in yet, with the most important at the top. Nothing there gets worked on until it moves to To do."},{"id":"sprint","g":"agile","word":"Sprint","text":"A short, fixed stretch of work (often one or two weeks, never more than a month) with a goal and an agreed set of cards to finish.","also":["sprints"]},{"id":"standup","g":"agile","word":"Stand-up","text":"A quick daily check-in: what each team member did, what they do next, and what's stopping them. In Scrum it's called the daily scrum.","also":["standup","stand-ups","daily scrum","daily stand-up"]},{"id":"kanban","g":"agile","word":"Kanban","text":"A way of working where cards move across a board’s columns (like To do, In progress, Done) and the team limits how much is in progress at once, so work keeps flowing."},{"id":"wip","g":"agile","word":"WIP limit","text":"WIP is short for work in progress. A WIP limit is the most cards a column should hold at once, so the team finishes things before starting more.","also":["WIP"]},{"id":"dod","g":"agile","word":"Definition of Done","text":"The team's short checklist of what “finished” means, like tested and explained, before a card's handed to you. Its twin, the Definition of Ready, says when a card's clear enough to start.","also":["Definition of Ready","DoD","DoR"]},{"id":"retro","g":"agile","word":"Retro","text":"A regular look back at how the team works, to agree on one or two things to do better next time. Short for retrospective. In AI-gile a retro suggests a change to the team’s ways of working, and you say Go or Not yet.","also":["retros","retrospective","retrospectives"]},{"id":"swarm","g":"agile","word":"Swarm","text":"All hands on deck: many people drop other work to fix one urgent thing together until it's sorted. In AI-gile every team helps on one project, and other projects wait meanwhile.","also":["swarming"]},{"id":"scrummaster","g":"agile","word":"Scrum Master","text":"In Scrum, the person who helps the team work well: clears what blocks them, keeps meetings on track and coaches good habits, without bossing anyone. In AI-gile the Lead Scrum Master spots stuck cards, nudges the teams and reminds you of what's waiting, across every project.","also":["Lead Scrum Master"]},{"id":"agile","g":"agile","word":"Agile","text":"A way of working in small steps: build a little, show real results often, learn from what people say and change the plan as you go, instead of planning everything up front.","also":["Agile development","agile ways of working"]},{"id":"manifesto","g":"agile","word":"Agile Manifesto","text":"A short statement written in 2001 by software makers. It puts people, working results, close work with customers and responding to change ahead of heavy plans and paperwork.","also":["Manifesto for Agile Software Development"]},{"id":"waterfall","g":"agile","word":"Waterfall","text":"The older way of working: plan everything, then build it all, then test it all, one stage after another. Changes late on are hard and costly.","also":["waterfall model"]},{"id":"iteration","g":"agile","word":"Iteration","text":"One round of building something, checking it and improving it. Agile work is a chain of these, and a sprint is one kind.","also":["iterations"]},{"id":"increment","g":"agile","word":"Increment","text":"A new working piece added to the product in a sprint or round of work, which fits in with what was already there.","also":["increments"]},{"id":"scrum","g":"agile","word":"Scrum","text":"A popular Agile way of working: a small team works in short sprints towards a goal, with set roles and a few regular meetings to plan, check and improve."},{"id":"scrumteam","g":"agile","word":"Scrum team","text":"The small group that does the work in Scrum: a product owner, a Scrum Master and the developers.","also":["Scrum teams"]},{"id":"ceremonies","g":"agile","word":"Scrum events","text":"The regular meetings in Scrum: sprint planning, the daily scrum, the sprint review and the retro. Many people call them ceremonies.","also":["ceremonies","Scrum ceremonies"]},{"id":"sprintplan","g":"agile","word":"Sprint planning","text":"The meeting at the start of a sprint where the team agrees why the sprint matters, which cards to take on and how to get started.","also":["planning meeting"]},{"id":"sprintgoal","g":"agile","word":"Sprint goal","text":"One sentence saying what a sprint is for. Small tasks can change along the way, as long as the goal is met.","also":["sprint goals"]},{"id":"sprintbacklog","g":"agile","word":"Sprint backlog","text":"The cards picked for the current sprint, with the team’s plan for getting them done.","also":["sprint backlogs"]},{"id":"productbacklog","g":"agile","word":"Product backlog","text":"The full ordered list of everything that might be built for the product, most important at the top. It keeps changing as you learn.","also":["product backlogs"]},{"id":"productgoal","g":"agile","word":"Product goal","text":"The bigger result the product is working towards, which helps the team choose what to do next.","also":["product goals"]},{"id":"refinement","g":"agile","word":"Backlog refinement","text":"Regularly going through the backlog to tidy up, split, order and add detail to cards, so they're ready to pick up. Also called backlog grooming.","also":["backlog grooming","refinement"]},{"id":"sprintreview","g":"agile","word":"Sprint review","text":"A meeting at the end of a sprint where the team shows what it finished and hears what people reckon, to decide what comes next.","also":["sprint reviews"]},{"id":"demo","g":"agile","word":"Demo","text":"Showing finished work actually working, live, to the people who asked for it.","also":["demos"],"noTip":1},{"id":"timebox","g":"agile","word":"Timebox","text":"A fixed amount of time for something. When it runs out you stop, even if not everything is done.","also":["timeboxed","timeboxes"]},{"id":"velocity","g":"agile","word":"Velocity","text":"How much work a team usually finishes in a sprint, used to plan how much to take on next time. It's not a score for how hard people work.","also":["team velocity"]},{"id":"capacity","g":"agile","word":"Capacity","text":"How much work the team can take on in a period, after holidays and other jobs.","noTip":1},{"id":"burndown","g":"agile","word":"Burndown chart","text":"A chart of the work left in a sprint going down day by day. If the line stays flat, something's stuck.","also":["burndown","burn-down chart"]},{"id":"burnup","g":"agile","word":"Burnup chart","text":"A chart of finished work going up over time, next to the total planned, so you can see when you'll get there.","also":["burnup","burn-up chart"]},{"id":"kanbanboard","g":"agile","word":"Kanban board","text":"The board itself: a column for each stage of the work, with cards moving across.","also":["Kanban boards"]},{"id":"pullsys","g":"agile","word":"Pull system","text":"A way of working where new work only starts when someone has room to take it on, rather than being dumped on a full plate.","also":["pull-based"]},{"id":"flow","g":"agile","word":"Flow","text":"How smoothly work moves across the board. Good flow means cards keep moving rather than piling up.","also":["flow of work"],"noTip":1},{"id":"leadtime","g":"agile","word":"Lead time","text":"How long it takes from someone asking for something to it being finished.","also":["lead times"]},{"id":"cycletime","g":"agile","word":"Cycle time","text":"How long a card takes from when work really starts on it to when it's finished.","also":["cycle times"]},{"id":"throughput","g":"agile","word":"Throughput","text":"How many cards get finished in a week, or in any set time.","also":["throughput rate"]},{"id":"bottleneck","g":"agile","word":"Bottleneck","text":"The one stage where work piles up and slows everything behind it, like the narrow neck of a bottle.","also":["bottlenecks"]},{"id":"swimlane","g":"agile","word":"Swimlane","text":"A row across the board that groups cards of one kind, such as urgent work or one team’s cards.","also":["swimlanes","swim lane"]},{"id":"lean","g":"agile","word":"Lean","text":"A way of working that cuts out waste (anything that doesn’t help the customer) and keeps work flowing."},{"id":"waste","g":"agile","word":"Waste","text":"In Lean, anything that takes effort but doesn’t help the customer, like waiting around, rework or building things nobody uses.","noTip":1},{"id":"kaizen","g":"agile","word":"Continuous improvement","text":"Getting a little better all the time through small regular changes, then checking they helped. Retros are one way to do it. Also called kaizen.","also":["kaizen"]},{"id":"selforg","g":"agile","word":"Self-organising team","text":"A team that decides for itself how to do the work, rather than being told step by step.","also":["self-organising","self-managing team"]},{"id":"crossfunc","g":"agile","word":"Cross-functional team","text":"A team that has all the skills it needs to finish the work itself, like design, building and testing.","also":["cross-functional"]},{"id":"spike","g":"agile","word":"Spike","text":"A short, timeboxed bit of research to answer a question before committing to the real work.","also":["spikes"]},{"id":"rework","g":"agile","word":"Rework","text":"Doing work again because it wasn’t right the first time.","also":["reworked"]},{"id":"safe","g":"agile","word":"Scaled Agile (SAFe)","text":"Ways of using Agile across many teams in a big organisation. SAFe (the Scaled Agile Framework) is one well known example.","also":["scaled Agile"]},{"id":"repo","g":"build","word":"Repo","text":"The project’s folder of code with its full history of commits. It can live on your computer, on GitHub, or both.","also":["repository"]},{"id":"branch","g":"build","word":"Branch","text":"A separate line of work in the code, so changes can be made without touching the main version.","also":["branches"]},{"id":"commit","g":"build","word":"Commit","text":"A saved snapshot of the code, with a short note of what changed. You can always go back to one.","also":["commits"]},{"id":"push","g":"build","word":"Push","text":"Sending your saved snapshots (commits) from this computer to the shared copy online, such as GitHub, so they're backed up and others can get them."},{"id":"merge","g":"build","word":"Merge","text":"Joining the changes from one branch into another, usually back into the main version."},{"id":"pr","g":"build","word":"Pull request","text":"Asking for a branch’s changes to be checked and merged into the main version. Some sites call it a merge request.","also":["PR","PRs","merge request"]},{"id":"refactor","g":"build","word":"Refactor","text":"Tidying the code without changing what it does: smaller files, clearer names, less repetition."},{"id":"bug","g":"build","word":"Bug","text":"Something that doesn’t work the way it should.","also":["bugs"]},{"id":"peerreview","g":"build","word":"Peer review","text":"A second pair of eyes: someone other than the author checks the work before it reaches you, so fewer mistakes get through. In AI-gile another AI checks each card.","also":["code review"]},{"id":"code","g":"build","word":"Code","text":"The written instructions that tell a computer what to do. Also called source code.","also":["source code"],"noTip":1},{"id":"proglang","g":"build","word":"Programming language","text":"A language for writing code, such as JavaScript, Python or Java. Different ones suit different jobs.","also":["programming languages"]},{"id":"developer","g":"build","word":"Developer (dev)","text":"Someone who writes and changes code. Also called a programmer or software engineer.","also":["developer","developers","programmer","programmers","software engineer"]},{"id":"software","g":"build","word":"Software","text":"Programs that run on computers and phones, as opposed to the machines themselves (the hardware).","noTip":1},{"id":"app","g":"build","word":"App","text":"Short for application: a program people use to get something done, on a phone, a computer or in a web browser.","also":["apps","application","applications"],"noTip":1},{"id":"webapp","g":"build","word":"Web app","text":"An app that runs in a web browser, so there's nothing to install.","also":["web apps","web application"]},{"id":"frontend","g":"build","word":"Front end","text":"The part of an app you see and click on: the screens, buttons and words, often in your browser.","also":["front-end","frontend"]},{"id":"backend","g":"build","word":"Back end","text":"The behind-the-scenes part of an app that keeps the data and does the work when you click something, like checking your password.","also":["back-end","backend"]},{"id":"fullstack","g":"build","word":"Full stack","text":"Working on both the front end and the back end.","also":["full-stack"]},{"id":"ui","g":"build","word":"User interface (UI)","text":"What a person sees and uses on screen: layout, buttons, menus and text.","also":["UI","user interface"]},{"id":"ux","g":"build","word":"User experience (UX)","text":"How it feels to use something: easy, clear and pleasant, or confusing and slow.","also":["UX","user experience"]},{"id":"accessibility","g":"build","word":"Accessibility (a11y)","text":"Making things usable by everyone, including people who can’t see well, can’t use a mouse or use a screen reader.","also":["a11y"]},{"id":"responsive","g":"build","word":"Responsive design","text":"Making pages fit and work well on any screen size, from a phone to a big monitor."},{"id":"designsys","g":"build","word":"Design system","text":"A shared kit of colours, fonts, buttons and rules, so every screen looks and behaves the same way.","also":["design systems"]},{"id":"architecture","g":"build","word":"Architecture","text":"The overall shape of a system: what the main parts are and how they talk to each other."},{"id":"database","g":"build","word":"Database (DB)","text":"An organised store of information, like a very powerful spreadsheet that the app can read and change.","also":["database","databases","DB"]},{"id":"schema","g":"build","word":"Database schema","text":"The layout of a database: which tables of information it has and what goes in each.","also":["schema"]},{"id":"sql","g":"build","word":"SQL","text":"Short for structured query language: the language used to ask many databases for information or to change it.","also":["Structured Query Language"]},{"id":"data","g":"build","word":"Data","text":"Information kept by a computer, like names, orders or settings.","also":["dataset","datasets"],"noTip":1},{"id":"server","g":"build","word":"Server","text":"A computer that's always on and answers requests from other computers, like sending a web page when you visit it.","also":["servers"]},{"id":"client","g":"build","word":"Client","text":"The side that asks for something, usually your browser or app, talking to a server. In business it also just means a customer.","also":["clients"],"noTip":1},{"id":"api","g":"build","word":"API","text":"Short for application programming interface: a set menu of requests one program can make to another, like asking a weather service for today’s forecast.","also":["APIs","application programming interface"]},{"id":"endpoint","g":"build","word":"Endpoint","text":"One item on an API’s menu: a web address a program can call to get or send something.","also":["endpoints"]},{"id":"integration","g":"build","word":"Integration","text":"Connecting two systems so they work together, like your shop sending orders to your accounts software.","also":["integrations"]},{"id":"webhook","g":"build","word":"Webhook","text":"A message one system sends to another by itself the moment something happens, like “payment received”.","also":["webhooks"]},{"id":"library","g":"build","word":"Library","text":"Ready-made code someone else wrote that you can reuse instead of writing it yourself.","also":["libraries"],"noTip":1},{"id":"framework","g":"build","word":"Framework","text":"A ready-made structure for building an app that decides much of how the code is laid out, like a house frame you fill in.","also":["frameworks"]},{"id":"sdk","g":"build","word":"Software development kit (SDK)","text":"A toolbox of tools, code and examples for building software for one platform or service.","also":["SDK","SDKs"]},{"id":"softdep","g":"build","word":"Software dependency","text":"A library or tool your code needs to work. Keeping them up to date matters for safety.","also":["software dependencies"]},{"id":"package","g":"build","word":"Package","text":"A bundle of ready-made code you can install and use in a project.","also":["packages"],"noTip":1},{"id":"pkgmgr","g":"build","word":"Package manager","text":"A tool that fetches and updates the packages your code depends on. npm is a common one.","also":["package managers","npm"]},{"id":"git","g":"build","word":"Git","text":"The most widely used tool for keeping the history of code changes, as commits and branches."},{"id":"github","g":"build","word":"GitHub","text":"A website that keeps Git repos online, so teams can share code, review changes and track work."},{"id":"vcs","g":"build","word":"Version control","text":"Keeping a full history of every change to the files, so you can see who changed what and go back if needed. Git does this.","also":["source control","version control system"]},{"id":"clone","g":"build","word":"Clone","text":"Making your own full copy of a repo, with its history, on your computer.","also":["cloned","cloning"]},{"id":"pull","g":"build","word":"Pull","text":"Fetching the latest commits from the shared copy (like GitHub) onto your computer. The opposite of push.","also":["git pull"],"noTip":1},{"id":"mainbranch","g":"build","word":"Main branch","text":"The official version of the code that everyone works from, often called main or master.","also":["master branch"]},{"id":"conflict","g":"build","word":"Merge conflict","text":"When two changes touch the same lines in different ways, so the computer can’t join them and a person has to choose.","also":["merge conflicts"]},{"id":"diff","g":"build","word":"Diff","text":"A view showing exactly what changed between two versions: lines added and lines taken away.","also":["diffs"]},{"id":"fork","g":"build","word":"Fork","text":"Your own copy of someone else’s repo, which you can change without affecting theirs.","also":["forks","forked"]},{"id":"script","g":"build","word":"Script","text":"A short program that does one job by itself, like tidying files or starting the app.","also":["scripts"],"noTip":1},{"id":"build","g":"build","word":"Build","text":"Turning the code into something ready to run, or the ready-to-run result itself.","also":["builds"],"noTip":1},{"id":"compile","g":"build","word":"Compile","text":"Translating code people wrote into a form the computer can run directly.","also":["compiler"]},{"id":"cli","g":"build","word":"Command line (CLI)","text":"A text window where you type instructions for the computer instead of clicking. Also called the terminal.","also":["command line","command-line","CLI","terminal"]},{"id":"config","g":"build","word":"Configuration (config)","text":"The settings that control how software behaves, kept apart from the code so they're easy to change.","also":["config","configuration"],"noTip":1},{"id":"envvar","g":"build","word":"Environment variable","text":"A setting handed to a program when it starts, often used for addresses or passwords so they aren’t written into the code.","also":["environment variables","env var"]},{"id":"debugging","g":"build","word":"Debugging","text":"Hunting down why something isn’t working, and fixing it.","also":["debug","debugged"]},{"id":"pairing","g":"build","word":"Pair programming","text":"Two people (or a person and an AI) working on the same code together, one typing and one checking.","also":["pairing"]},{"id":"docs","g":"build","word":"Documentation (docs)","text":"Written explanations of how something works or how to use it.","also":["documentation","docs"],"noTip":1},{"id":"readme","g":"build","word":"README","text":"The first file to read in a repo: what the project is and how to get it going.","also":["READMEs"]},{"id":"legacy","g":"build","word":"Legacy system","text":"An older system still in use that's hard to change, often because hardly anyone still understands it.","also":["legacy systems","legacy code"]},{"id":"techdebt","g":"build","word":"Technical debt","text":"Shortcuts that save time now but make later changes slower, like a loan that builds up interest. Refactoring pays it down.","also":["tech debt"]},{"id":"test","g":"test","word":"Test","text":"A check that something works the way it should. Some tests the computer runs by itself every time the code changes; others are you trying a finished card before you accept it.","also":["tests"],"noTip":1},{"id":"qa","g":"test","word":"QA","text":"Short for quality assurance: everything done to make sure work is right before it goes live. In AI-gile that means the automatic checks: when QA is red, something failed, and it can’t go live until that's fixed.","also":["quality checks"]},{"id":"testpile","g":"test","word":"Test pile","text":"The finished cards waiting for you to try, one after the other. Accept one or send it back with a note, and the next one comes up.","also":["test piles"]},{"id":"autotest","g":"test","word":"Automated test","text":"A check the computer runs by itself every time the code changes, to catch mistakes early.","also":["automated tests","automatic tests"]},{"id":"manualtest","g":"test","word":"Manual test","text":"A person trying the work by hand to see if it behaves as it should.","also":["manual tests","manual testing"]},{"id":"unittest","g":"test","word":"Unit test","text":"A small automatic check of one tiny piece of code on its own.","also":["unit tests"]},{"id":"integtest","g":"test","word":"Integration test","text":"A check that several parts work properly together, not just one at a time.","also":["integration tests"]},{"id":"endtoend","g":"test","word":"End-to-end test (E2E)","text":"A test that acts like a real user from start to finish, such as signing up, buying and paying.","also":["E2E","end-to-end tests"]},{"id":"uat","g":"test","word":"User acceptance testing (UAT)","text":"The people who asked for the work try it themselves and say whether it does what they need. AI-gile’s test pile is its version of this.","also":["UAT","acceptance testing"]},{"id":"regression","g":"test","word":"Regression","text":"Something that used to work but broke after a change. Regression tests check that the old things still work.","also":["regressions","regression test","regression tests","regression testing"]},{"id":"smoke","g":"test","word":"Smoke test","text":"A very quick check that the main things work at all, for example right after a change goes live. If it fails, stop and have a look.","also":["smoke tests"]},{"id":"exploratory","g":"test","word":"Exploratory testing","text":"Trying the product freely and poking at it in different ways, to find problems that planned checks would miss.","also":["exploratory test","exploratory tests"]},{"id":"testcase","g":"test","word":"Test case","text":"One written scenario to try: the steps, and what should happen.","also":["test cases"]},{"id":"coverage","g":"test","word":"Test coverage","text":"How much of the code is checked by automatic tests. More is usually safer, but high coverage alone doesn’t prove it works well.","also":["code coverage"]},{"id":"testdata","g":"test","word":"Test data","text":"Made-up example information used while testing, so no real person’s private details are exposed.","also":["test fixtures"]},{"id":"edgecase","g":"test","word":"Edge case","text":"An unusual situation at the limits, like an empty form or a name with an apostrophe, where things often fall over.","also":["edge cases"]},{"id":"happypath","g":"test","word":"Happy path","text":"The normal route where everything goes right. Good testing also tries the unhappy paths."},{"id":"perftest","g":"test","word":"Performance testing","text":"Checking how fast something is and how well it copes under strain.","also":["performance test","performance tests"]},{"id":"loadtest","g":"test","word":"Load testing","text":"Checking how a system copes when heaps of people use it at once.","also":["load test","load tests"]},{"id":"sectest","g":"test","word":"Security testing","text":"Looking for weaknesses that could let someone misuse a system or see what they shouldn’t.","also":["security test","security tests"]},{"id":"accesstest","g":"test","word":"Accessibility testing","text":"Checking that people with different abilities can use the product, including with a screen reader or only a keyboard.","also":["accessibility test"]},{"id":"linting","g":"test","word":"Linting","text":"An automatic check that spots likely mistakes and messy style in code, like a spelling checker for programs.","also":["linter","lint"]},{"id":"static","g":"test","word":"Static analysis","text":"Checking code for problems by reading it automatically, without running it.","also":["static code analysis"]},{"id":"flaky","g":"test","word":"Flaky test","text":"A test that sometimes passes and sometimes fails for no clear reason, so it can’t be fully trusted.","also":["flaky tests"]},{"id":"repro","g":"test","word":"Reproduce (repro)","text":"Making a bug happen again on purpose by following the same steps, so it can be studied and fixed. Writing those steps down is the most useful part of a bug report.","also":["repro","reproduce","steps to reproduce"]},{"id":"severity","g":"test","word":"Severity","text":"How bad a problem’s effect is, from a small annoyance to everything grinding to a halt.","also":["severity level"]},{"id":"deploy","g":"change","word":"Deploy","text":"Copying a new version of the software onto the computers that run it, such as a test copy or the live service."},{"id":"release","g":"change","word":"Release","text":"A named bundle of finished work that goes live together, with short notes on what changed. 🚀 Releases writes the notes from the done cards.","also":["releases"]},{"id":"rollback","g":"change","word":"Roll back","text":"Going back to the last version that worked when a new one causes strife. In AI-gile, Roll back gathers the undo steps written on each change into one checklist.","also":["rollback","roll-back","rolled back"]},{"id":"live","g":"change","word":"Live","text":"The real version people use, not a copy for mucking around on. Developers also call it production.","also":["production"],"noTip":1},{"id":"change","g":"change","word":"Change","text":"A planned change to something people rely on, written down first: what, why, the risk, when, and how to undo it. Kick one off with 🔀 Raise a change.","also":["change request","change requests"],"noTip":1},{"id":"risk","g":"change","word":"Risk","text":"Something that could go pear-shaped, scored on how likely and how bad it'd be. ⚠️ Risks keeps them in one list, highest score first, each with a date to have another look.","also":["risks","risk register"]},{"id":"chgwin","g":"change","word":"Change window","text":"The times when changes can go live, like a quiet Tuesday arvo. Outside a window a change card can't be finished, unless it's an emergency.","also":["change windows"]},{"id":"gonogo","g":"change","word":"Go / no go","text":"A last check just before a change goes live: each person who has to approve says Go or No go. It only goes ahead when everyone says Go.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Approval","text":"Waiting on a yes before work starts. A card a mate raises, or a change, waits in ✅ Approvals till you approve or knock it back.","also":["approvals"]},{"id":"quiettime","g":"change","word":"Quiet time","text":"A stretch of time, like during a live stream, a demo or overnight, when nothing goes live. The teams keep working and testing, but going live waits until it ends. Elsewhere it's called a change freeze.","also":["quiet times","change freeze"]},{"id":"devops","g":"change","word":"DevOps","text":"A way of working where the people who build software and the people who run it work as one team, with lots of automation, so changes go live often and safely."},{"id":"cicd","g":"change","word":"CI/CD (continuous integration and delivery)","text":"Everyone’s changes are joined into the main version often and checked automatically each time (continuous integration), so the software is always ready to go live at the press of a button (continuous delivery).","also":["CI/CD","CI","CD","continuous integration","continuous delivery"]},{"id":"contdeploy","g":"change","word":"Continuous deployment","text":"One step further than continuous delivery: every change that passes the checks goes live by itself, with no button to press.","also":["continuous deployments"]},{"id":"pipeline","g":"change","word":"Pipeline","text":"The automatic series of steps a change goes through on its way to live, like build, test, then deploy.","also":["pipelines"]},{"id":"environment","g":"change","word":"Environment","text":"One separate copy of the system for one purpose, such as one to build in, one to test in and the live one.","also":["environments"],"noTip":1},{"id":"devenv","g":"change","word":"Development environment","text":"The copy a developer works in, often on their own computer, where breaking things harms nobody.","also":["dev environment"]},{"id":"testenv","g":"change","word":"Test environment","text":"A separate copy of the system used just for testing, so the real service isn’t touched.","also":["test environments"]},{"id":"staging","g":"change","word":"Staging","text":"A last copy set up just like live, for a final check before a change goes live.","also":["staging environment"]},{"id":"artifact","g":"change","word":"Build artifact","text":"The file or bundle a build produces, ready to be stored, checked or put live.","also":["build artifacts"]},{"id":"hotfix","g":"change","word":"Hotfix","text":"An urgent fix put live quickly, outside the normal plan, because something important is broken.","also":["hotfixes"]},{"id":"patch","g":"change","word":"Patch","text":"A small update that fixes a bug or closes a security hole. Applying security patches quickly matters.","also":["patches","security patch","security patches"]},{"id":"version","g":"change","word":"Version number","text":"A label like 2.4.1 that says which release you've got. Often the first number changes for big changes and the last for small fixes.","also":["version numbers","semantic versioning"]},{"id":"relnotes","g":"change","word":"Release notes","text":"A short plain list of what changed in a release, for the people who use it, including fixes and known limits. Also called a changelog.","also":["changelog","change log"]},{"id":"flag","g":"change","word":"Feature flag","text":"An on and off switch for a feature, so new work can go live hidden and be turned on (or off again) without a new release.","also":["feature flags","feature toggle","feature toggles"]},{"id":"rollfwd","g":"change","word":"Roll forward","text":"Fixing a bad release by quickly putting out a new, corrected version instead of going back to the old one.","also":["rolling forward","rolled forward"]},{"id":"canary","g":"change","word":"Canary release","text":"Putting a change live for a small group first, and for everyone only once it looks fine. Named after the canaries miners took underground as an early warning.","also":["canary releases","canary"]},{"id":"bluegreen","g":"change","word":"Blue-green deployment","text":"Keeping two copies of the live system and switching people over to the new one in one go, so you can switch straight back if it goes pear-shaped.","also":["blue-green","blue green deployment"]},{"id":"zerodown","g":"change","word":"Zero-downtime deployment","text":"Putting a new version live without the service ever stopping for its users.","also":["zero downtime","zero-downtime"]},{"id":"chgenable","g":"change","word":"Change enablement","text":"Helping changes succeed: weighing the risk, getting the right approval and picking a good time. Also called change management.","also":["change management"]},{"id":"cab","g":"change","word":"Change advisory board (CAB)","text":"A group that looks over important changes and agrees whether and when they can go ahead.","also":["CAB"]},{"id":"stdchange","g":"change","word":"Standard change","text":"A low-risk change done the same tried and tested way each time, so it's approved in advance.","also":["standard changes"]},{"id":"normchange","g":"change","word":"Normal change","text":"A change that needs to be checked and approved before it goes ahead.","also":["normal changes"]},{"id":"emergchange","g":"change","word":"Emergency change","text":"A change that has to happen right away to fix or prevent serious trouble, with a quicker approval to match.","also":["emergency changes"]},{"id":"automation","g":"change","word":"Automation","text":"Getting the computer to do a repeated job by itself, so it's quicker and done the same way every time.","also":["automated"],"noTip":1},{"id":"infra","g":"change","word":"Infrastructure","text":"The machines, networks and services that software runs on.","also":["infra"]},{"id":"iac","g":"change","word":"Infrastructure as code (IaC)","text":"Describing your servers and settings in files kept with the code, so they can be rebuilt exactly the same way every time.","also":["IaC"]},{"id":"cloud","g":"change","word":"Cloud","text":"Renting computers, storage and services from a big provider over the internet, instead of owning the machines yourself.","also":["the cloud","cloud computing"]},{"id":"provider","g":"change","word":"Cloud provider","text":"A company that rents out computing over the internet, such as Amazon Web Services (AWS), Microsoft Azure or Google Cloud.","also":["cloud providers"]},{"id":"hosting","g":"change","word":"Hosting","text":"Where your app or website lives and runs so people can reach it, usually rented from a company."},{"id":"domain","g":"change","word":"Domain name","text":"The web address people type, like example.com. You rent it by the year, so it has to be renewed.","also":["domain names","domain"]},{"id":"dns","g":"change","word":"DNS","text":"Short for domain name system: the internet’s address book, which turns a name like example.com into the address of the right computer.","also":["domain name system"]},{"id":"container","g":"change","word":"Container","text":"A sealed package holding an app and everything it needs, so it runs the same on any computer. Docker is the best known tool.","also":["containers","Docker"],"noTip":1},{"id":"vm","g":"change","word":"Virtual machine (VM)","text":"A pretend computer running inside a real one, so one big machine can act as many.","also":["VM","VMs","virtual machines"]},{"id":"serverless","g":"change","word":"Serverless","text":"Running code without looking after any servers yourself: the provider runs it when needed and you pay for what you use."},{"id":"lb","g":"change","word":"Load balancer","text":"Something that spreads visitors across several servers, so no single one gets swamped.","also":["load balancers"]},{"id":"cache","g":"change","word":"Cache","text":"A handy store of recent results kept close by, so the same thing doesn’t have to be fetched or worked out again. Clearing it can fix pages that look out of date.","also":["caches","caching","cached"]},{"id":"cdn","g":"change","word":"Content delivery network (CDN)","text":"A worldwide set of servers holding copies of your pages and pictures near your visitors, so they load quickly.","also":["CDN"]},{"id":"migration","g":"change","word":"Migration","text":"Moving data or systems from an old setup to a new one, or carefully changing how a database is laid out.","also":["migrations","database migration"]},{"id":"service","g":"run","word":"Service","text":"Something you built that people rely on, like a website or an app, looked after so it keeps working. Tick “This project is a service” and say what it offers, who uses it and who's on call.","also":["services"]},{"id":"uptimepct","g":"run","word":"Uptime","text":"How much of the time a service is working, usually as a percentage. 99.9% still allows about 43 minutes down a month.","also":["uptime percentage"]},{"id":"uptime","g":"run","word":"Uptime check","text":"An automatic check, every few minutes, that your service still answers. If it fails a few times in a row, AI-gile opens an incident card all by itself.","also":["uptime checks"]},{"id":"statuspage","g":"run","word":"Status page","text":"A public page that shows whether a service is working (green, orange or red) with the latest update, so the folks who use it can check instead of asking.","also":["status pages"]},{"id":"desk","g":"run","word":"Service desk","text":"Where questions and reports from the people using your service land. AI-gile sorts each one into a request, an incident or an idea, and gives you a heads-up when it looks like something already reported.","also":["service desks","help desk","helpdesk"]},{"id":"svcrequest","g":"run","word":"Service request","text":"Someone asking for something everyday, like a new account or a hand with something, rather than reporting that something's busted. It waits its turn; an incident goes first.","also":["service requests"]},{"id":"incident","g":"run","word":"Incident","text":"Something that's broken or not working properly for the people using it right now, like the website being down or very slow. A 🔥 incident card jumps the queue: getting it working again comes first.","also":["incidents"]},{"id":"major","g":"run","word":"Major incident","text":"A big incident: heaps of people affected, or money or data at risk. One button puts every team on it (swarm), wakes whoever's on call and asks for a status update every 30 minutes.","also":["major incidents"]},{"id":"oncall","g":"run","word":"On call","text":"Being the one who answers when something carks it, even in the middle of the night. Each service has an on-call team member who gets woken first for its incidents.","also":["on-call"]},{"id":"replyby","g":"run","word":"Reply-by time","text":"How long a card can wait for a first answer, say an hour for an incident. After that it gets a red clock, so nothing gets quietly forgotten. Also called a response target.","also":["reply-by times","response target","response targets"]},{"id":"postmortem","g":"run","word":"Post-mortem","text":"A short look back after an incident: what happened, what helped and what to change, without blaming anyone. An incident can't be closed without one.","also":["post-mortems","postmortem","post-incident review"]},{"id":"problem","g":"run","word":"Problem","text":"The hidden cause behind one or more incidents. A 🧩 problem card groups incidents that keep coming back, so the cause gets found and fixed for good.","also":["problems"],"noTip":1},{"id":"rootcause","g":"run","word":"Root cause","text":"The real reason something broke, not just what you saw going wrong. Fix the root cause and the incident stops coming back.","also":["root causes"]},{"id":"workaround","g":"run","word":"Workaround","text":"A way to keep things ticking over till the real fix is ready, like restarting something when it gets stuck. It's written on the problem card so nobody has to work it out again.","also":["workarounds"]},{"id":"knownerror","g":"run","word":"Known error","text":"A problem whose cause is understood but isn’t fixed yet, usually with a workaround written down. 🧩 Known errors lists them, so everyone uses the workaround instead of digging around again.","also":["known errors"]},{"id":"runbook","g":"run","word":"Runbook","text":"Step-by-step instructions for fixing a known kind of trouble, so it's done the same way, quick smart, every time. After a big incident the team can suggest one for you to OK.","also":["runbooks"]},{"id":"ci","g":"run","word":"Configuration item","text":"One thing your service leans on, like a server, a domain, a certificate, a key or a supplier. 🗂️ Configuration items lists them per service, so you can see what an incident hits and what needs renewing or a backup.","also":["configuration items"]},{"id":"expiry","g":"run","word":"Expiry date","text":"The date something stops working unless it's renewed, like a website’s security certificate or its web address. AI-gile watches these dates and makes one card to renew each one 30 days before, so nothing stops by surprise.","also":["expiry dates","expiry","expiry watch"]},{"id":"backup","g":"run","word":"Backup","text":"A saved copy of your data from earlier, to fall back on if something's lost or damaged. AI-gile makes a backup of your boards every day.","also":["backups","back-up","back-ups"]},{"id":"restore","g":"run","word":"Restore","text":"Putting data back from a backup. A backup only really counts once you know it can be restored, so it's worth giving it a burl now and then.","also":["restored"]},{"id":"svcreview","g":"run","word":"Service review","text":"A look back at one month of a service: incidents opened and fixed, how quickly people got an answer, uptime and tokens used. The Monthly review shows it for each service.","also":["service reviews","monthly review","monthly reviews"]},{"id":"accessreview","g":"run","word":"Access review","text":"Checking every 90 days who can still get in: share links, mates' roles and saved passwords and keys. You keep or remove each one, so old access doesn’t linger.","also":["access reviews"]},{"id":"improvements","g":"run","word":"Improvement list","text":"Everything the team decided to get better at, in one place: retro suggestions, review actions and problem fixes, each with its status. Find it under 📈 Improvements.","also":["improvement lists","improvements"]},{"id":"tokencap","g":"run","word":"Token cap","text":"A monthly limit on the tokens a service's agents can use. At 80% you get a warning; at 100% their background work waits till next month or till you raise the cap.","also":["token caps"]},{"id":"svcmgmt","g":"run","word":"Service management","text":"Everything involved in keeping a service useful and working for the people who rely on it, day after day."},{"id":"itil","g":"run","word":"ITIL","text":"A widely used guide to good service management, covering things like incidents, problems and changes. The name once stood for IT Infrastructure Library."},{"id":"itsm","g":"run","word":"IT service management (ITSM)","text":"Running technology as a service for people, with clear ways to handle requests, incidents, changes and improvements.","also":["ITSM"]},{"id":"managed","g":"run","word":"Managed service","text":"A service someone else runs and looks after for you, under an agreement about how well it has to work.","also":["managed services"]},{"id":"svcowner","g":"run","word":"Service owner","text":"The person who answers for a service as a whole: how well it works, what it costs and how it improves.","also":["service owners"]},{"id":"sla","g":"run","word":"Service level agreement (SLA)","text":"A written promise to customers about how well a service will work, like “up 99.9% of the time” or “answered within an hour”, often with money back if it's broken.","also":["SLA","SLAs","service level agreement"]},{"id":"slo","g":"run","word":"Service level objective (SLO)","text":"The team’s own target for how well a service should work over a period, usually set a bit stricter than the SLA to be safe.","also":["SLO","SLOs"]},{"id":"sli","g":"run","word":"Service level indicator (SLI)","text":"The actual measurement you check against a target, like the share of visits that loaded fine.","also":["SLI","SLIs"]},{"id":"availability","g":"run","word":"Availability","text":"Whether people can use a service when they need it, often measured as uptime.","also":["high availability"]},{"id":"downtime","g":"run","word":"Downtime","text":"Time when a service isn’t working or is switched off, planned or not.","also":["down time"]},{"id":"errorbudget","g":"run","word":"Error budget","text":"The small amount of failure your reliability target allows. While some is left you can take risks with changes; once it's used up, you slow down.","also":["error budgets"]},{"id":"outage","g":"run","word":"Outage","text":"A time when a service is down or badly broken for its users.","also":["outages"]},{"id":"degraded","g":"run","word":"Degraded","text":"Working, but crook: slow, or with some parts not working.","also":["degraded service"]},{"id":"monitoring","g":"run","word":"Monitoring","text":"Watching a service automatically all the time, so problems are spotted, ideally before users notice."},{"id":"observability","g":"run","word":"Observability","text":"How well you can tell what's going on inside a system from the outside, using its logs, numbers and traces.","also":["o11y"]},{"id":"log","g":"run","word":"Log","text":"A running diary a program keeps of what it's doing, used to work out what went wrong.","also":["logs","logging"],"noTip":1},{"id":"trace","g":"run","word":"Trace","text":"A record of how one request travels through the different parts of a system, step by step, showing where it slowed down.","also":["traces","tracing"]},{"id":"latency","g":"run","word":"Latency","text":"How long something takes to answer, like the wait between clicking and the page appearing."},{"id":"alert","g":"run","word":"Alert","text":"An automatic message that something needs attention, like the website not answering.","also":["alerts","alerting"],"noTip":1},{"id":"alertfatigue","g":"run","word":"Alert fatigue","text":"When there are so many alerts that people start ignoring them, including the important ones.","also":["alarm fatigue"]},{"id":"dashboard","g":"run","word":"Dashboard","text":"A screen showing the most important numbers and statuses at a glance.","also":["dashboards"],"noTip":1},{"id":"paging","g":"run","word":"Paging","text":"Urgently calling or waking the on-call person about a problem.","also":["paged"]},{"id":"escalation","g":"run","word":"Escalation","text":"Bringing in someone with more skill or authority when an issue can’t be sorted at the current level, or not fast enough.","also":["escalate","escalated"]},{"id":"triage","g":"run","word":"Triage","text":"Quickly sorting incoming issues by how urgent and important they are, so the worst gets handled first.","also":["triaged"]},{"id":"impact","g":"run","word":"Impact","text":"How much something affects people: how many, and how badly.","noTip":1},{"id":"urgency","g":"run","word":"Urgency","text":"How quickly something needs to be dealt with. Impact and urgency together set the priority.","noTip":1},{"id":"plevels","g":"run","word":"Priority levels (P1, P2…)","text":"Labels for how urgent an issue is. P1 is the most serious and needs action straight away.","also":["P1","P2","P3","P4"]},{"id":"queue","g":"run","word":"Ticket queue","text":"The list of requests and incidents waiting to be picked up.","also":["ticket queues"]},{"id":"tiers","g":"run","word":"First line and second line","text":"Levels of support: first line takes the call and fixes simple things; second line has deeper skills for harder ones. Also called tier 1 and tier 2.","also":["first-line support","tier 1","tier 2"]},{"id":"ic","g":"run","word":"Incident commander","text":"The one person who leads the response to an incident, so everyone knows who makes the calls and who does what.","also":["incident commanders"]},{"id":"responsetime","g":"run","word":"Response time","text":"How long it takes before someone first picks up a request or incident.","also":["response times"]},{"id":"resolution","g":"run","word":"Resolution time","text":"How long it takes to fully sort out a request or incident, from report to fixed.","also":["resolution times","time to resolve"]},{"id":"mttr","g":"run","word":"Mean time to recover (MTTR)","text":"On average, how long it takes to get a service working again after it breaks. MTTR can mean slightly different things, so say what you're measuring.","also":["MTTR","mean time to restore"]},{"id":"mtbf","g":"run","word":"Mean time between failures (MTBF)","text":"On average, how long a service runs before something breaks.","also":["MTBF"]},{"id":"cmdb","g":"run","word":"Configuration management database (CMDB)","text":"The list of all your configuration items and how they connect, so you can see what depends on what.","also":["CMDB"]},{"id":"asset","g":"run","word":"Asset","text":"Anything of value you own or pay for to run the service, like a laptop, a software licence or a domain.","also":["assets"],"noTip":1},{"id":"capplan","g":"run","word":"Capacity planning","text":"Making sure there'll be enough computer power, storage and people for what's coming.","also":["capacity plan"]},{"id":"scaling","g":"run","word":"Scaling","text":"Coping with more users by giving a machine more power (scaling up) or adding more machines (scaling out).","also":["scale up","scale out","scaling up","scaling out"]},{"id":"bcp","g":"run","word":"Business continuity","text":"Plans for keeping the important things going when something big goes wrong, like losing an office, a key supplier or the computers.","also":["business continuity plan"]},{"id":"dr","g":"run","word":"Disaster recovery (DR)","text":"The plan and tools for getting a service back after something serious, like losing a whole data centre.","also":["disaster recovery"]},{"id":"rto","g":"run","word":"Recovery time objective (RTO)","text":"The longest a service can be down after a disaster before it has to be working again.","also":["RTO"]},{"id":"rpo","g":"run","word":"Recovery point objective (RPO)","text":"How much recent data you could afford to lose, measured in time. An RPO of one hour means backups at least every hour.","also":["RPO"]},{"id":"redundancy","g":"run","word":"Redundancy","text":"Having spares ready, like a second server, so one failure doesn’t stop the service."},{"id":"failover","g":"run","word":"Failover","text":"Switching over to a spare system by itself when the usual one fails.","also":["fail over"]},{"id":"spof","g":"run","word":"Single point of failure","text":"One part that takes everything down with it when it breaks, because there's no spare.","also":["single points of failure","SPOF"]},{"id":"maintwin","g":"run","word":"Maintenance window","text":"A planned time when a service may be paused or slow for upkeep, announced to users in advance.","also":["maintenance windows","planned maintenance"]},{"id":"handover","g":"run","word":"Handover","text":"Passing work, knowledge and responsibility to another person or team, so nothing gets dropped.","also":["handovers"]},{"id":"kb","g":"run","word":"Knowledge base","text":"A collection of help articles and answers, for users and for the team.","also":["knowledge bases"]},{"id":"csat","g":"run","word":"Customer satisfaction (CSAT)","text":"A score from users saying how happy they were, often asked after a request is closed.","also":["CSAT"]},{"id":"supplier","g":"run","word":"Supplier","text":"An outside company you rely on, like your hosting provider. Also called a vendor or third party.","also":["suppliers","vendor","vendors","third party"],"noTip":1},{"id":"retire","g":"run","word":"Service retirement","text":"Switching a service off for good, safely: telling its users, dealing with its data and access, and stopping its costs.","also":["retiring a service"]},{"id":"eol","g":"run","word":"End of life (EOL)","text":"When a product stops getting updates or support from its maker, so it should be replaced.","also":["EOL","end-of-life"]},{"id":"cybersec","g":"sec","word":"Cybersecurity","text":"Protecting systems and data from being broken into, stolen or damaged.","also":["cyber security"]},{"id":"authn","g":"sec","word":"Authentication","text":"Checking who someone is, usually with a password or a code. Often shortened to authn.","also":["authn"]},{"id":"authz","g":"sec","word":"Authorisation","text":"Checking what someone is allowed to do once you know who they are. Often shortened to authz.","also":["authz","authorization"]},{"id":"mfa","g":"sec","word":"Multi-factor authentication (MFA)","text":"Logging in with two or more proofs, like a password plus a code on your phone. Also called two-factor (2FA).","also":["MFA","2FA","two-factor","two-factor authentication"]},{"id":"sso","g":"sec","word":"Single sign-on (SSO)","text":"Logging in once to get into many systems, like using your work account everywhere.","also":["SSO"]},{"id":"pwmgr","g":"sec","word":"Password manager","text":"An app that creates strong passwords and remembers them for you.","also":["password managers"]},{"id":"secret","g":"sec","word":"Secret","text":"A password, key or other private code a program uses to get into something. It must never be shared or written into the code.","also":["secrets"],"noTip":1},{"id":"apikey","g":"sec","word":"API key","text":"A secret code that lets a program use another service’s API, and shows who's using (and paying for) it.","also":["API keys"]},{"id":"accesstoken","g":"sec","word":"Access token","text":"A temporary pass that proves a program is allowed in, so it doesn’t need your password each time. Not the same as an AI token.","also":["access tokens"]},{"id":"encryption","g":"sec","word":"Encryption","text":"Scrambling information so only someone with the right key can read it.","also":["encrypted","encrypt"]},{"id":"https","g":"sec","word":"HTTPS","text":"The secure way web pages travel, shown by the padlock in your browser, so nobody in between can read or change them."},{"id":"cert","g":"sec","word":"SSL/TLS certificate","text":"A digital ID card that lets a website prove who it is and use HTTPS. It expires, so it has to be renewed.","also":["TLS certificate","SSL certificate","certificate","certificates"]},{"id":"permissions","g":"sec","word":"Permissions","text":"The rules for who can see or change what.","also":["permission"],"noTip":1},{"id":"leastpriv","g":"sec","word":"Least privilege","text":"Giving each person or program only the access they truly need, for only as long as they need it.","also":["principle of least privilege"]},{"id":"rbac","g":"sec","word":"Role-based access control (RBAC)","text":"Giving access by role, like viewer or editor, rather than person by person.","also":["RBAC","role-based access"]},{"id":"vuln","g":"sec","word":"Vulnerability","text":"A weakness that someone could use to break in or cause harm.","also":["vulnerabilities"]},{"id":"zeroday","g":"sec","word":"Zero-day","text":"A weakness attackers know about before the makers have had any time to fix it.","also":["zero-days","zero day"]},{"id":"malware","g":"sec","word":"Malware","text":"Harmful software, like viruses, made to damage, spy or steal."},{"id":"ransomware","g":"sec","word":"Ransomware","text":"Malware that locks up your files and demands money to unlock them. Good backups are the best defence.","also":["ransomware attack"]},{"id":"phishing","g":"sec","word":"Phishing","text":"Fake messages that try to trick you into giving away passwords or money, or opening something harmful.","also":["phishing email","phishing emails"]},{"id":"socialeng","g":"sec","word":"Social engineering","text":"Tricking people, rather than computers, into giving access, like a fake call from “IT support”."},{"id":"firewall","g":"sec","word":"Firewall","text":"A guard that decides which network traffic can come in or go out.","also":["firewalls"]},{"id":"vpn","g":"sec","word":"VPN","text":"Short for virtual private network: a private, scrambled link over the internet, often used to reach work systems safely.","also":["virtual private network"]},{"id":"ddos","g":"sec","word":"Denial of service (DoS, DDoS)","text":"Flooding a service with so much fake traffic that real people can’t use it. DDoS means it comes from many computers at once.","also":["DoS","DDoS","denial of service","DDoS attack"]},{"id":"pentest","g":"sec","word":"Penetration test (pen test)","text":"Hiring friendly experts to try to break in, so weaknesses are found before real attackers find them.","also":["pen test","pen testing","penetration testing","pentest"]},{"id":"audit","g":"sec","word":"Security audit","text":"A careful check of how well something is protected, against a list of good practice.","also":["security audits"]},{"id":"threatmodel","g":"sec","word":"Threat modelling","text":"Thinking through who might attack something, how, and what you'd do to stop them.","also":["threat model","threat modeling"]},{"id":"breach","g":"sec","word":"Data breach","text":"When private information gets out to people who shouldn’t have it, or is lost or changed without permission.","also":["data breaches"]},{"id":"pii","g":"sec","word":"Personal data","text":"Any information about a person who can be identified, like a name, email address or location. Also called PII.","also":["PII","personally identifiable information"]},{"id":"gdpr","g":"sec","word":"GDPR","text":"The European law on personal data (the UK has its own version): collect only what you need, keep it safe, and let people see or delete theirs.","also":["General Data Protection Regulation"]},{"id":"dataprot","g":"sec","word":"Data protection","text":"Looking after personal data properly and within the law.","also":["data protection law"]},{"id":"privacypolicy","g":"sec","word":"Privacy policy","text":"A public page saying what personal data you collect, why, and what you do with it.","also":["privacy statement","privacy notice"]},{"id":"consent","g":"sec","word":"Consent","text":"A person’s clear, free yes to their data being used in a particular way. They can take it back at any time.","also":["opt-in"],"noTip":1},{"id":"cookie","g":"sec","word":"Cookie","text":"A small file a website saves in your browser to remember things, like being logged in. Some need your consent first.","also":["cookies"],"noTip":1},{"id":"minimisation","g":"sec","word":"Data minimisation","text":"Collecting and keeping only the personal data you really need for the job.","also":["data minimization"]},{"id":"retention","g":"sec","word":"Data retention","text":"How long data is kept before it's deleted. Keeping it no longer than needed is safer and often the law.","also":["retention period"]},{"id":"anon","g":"sec","word":"Anonymisation","text":"Changing data so nobody can reasonably be identified from it any more.","also":["anonymised","anonymization","anonymous data"]},{"id":"pseudo","g":"sec","word":"Pseudonymisation","text":"Swapping names and other details for codes, with a key kept apart to link them back. It's still personal data.","also":["pseudonymised","pseudonymization"]},{"id":"dpa","g":"sec","word":"Data processing agreement (DPA)","text":"A contract saying how a supplier can handle personal data on your behalf.","also":["DPA"]},{"id":"dpia","g":"sec","word":"Data protection impact assessment (DPIA)","text":"A careful look, before you start, at how a plan to use personal data could affect people and how to lower the risks.","also":["DPIA"]},{"id":"auditlog","g":"sec","word":"Audit log","text":"A record of who did what and when, so actions can be checked later.","also":["audit logs","audit trail"]},{"id":"compliance","g":"sec","word":"Compliance","text":"Following the laws, rules and standards that apply to you, and being able to show that you do.","also":["compliant"]},{"id":"iso","g":"sec","word":"ISO 27001","text":"A well known international standard for managing information security. Companies can be certified against it.","also":["ISO/IEC 27001"]},{"id":"soc","g":"sec","word":"SOC 2","text":"A US report, checked by outside auditors, showing a company looks after customer data properly.","also":["SOC2"]},{"id":"agent","g":"ai","word":"Agent","text":"An AI that works on a task by itself: reads the code, makes changes, runs checks and reports back. Its work still gets checked.","also":["agents"]},{"id":"token","g":"ai","word":"Token","text":"The small pieces of text an AI reads and writes, about three quarters of a word each. AI use is counted in tokens, so fewer tokens leave more of your plan.","also":["tokens"]},{"id":"hook","g":"ai","word":"Hook","text":"A small command that runs by itself at a set moment, for example when an AI session starts, so the team hears your comments.","also":["hooks"]},{"id":"ai","g":"ai","word":"Artificial intelligence (AI)","text":"Computer systems that do things we usually think need a person, like writing, answering questions or recognising pictures.","also":["AI","artificial intelligence"],"noTip":1},{"id":"ml","g":"ai","word":"Machine learning (ML)","text":"A way of making computers learn patterns from lots of examples, instead of giving them exact rules.","also":["machine learning"]},{"id":"model","g":"ai","word":"Model","text":"The trained “brain” of an AI system, built by learning from huge numbers of examples. Models differ in skill, speed and price.","also":["models","AI model"],"noTip":1},{"id":"llm","g":"ai","word":"Large language model (LLM)","text":"An AI model trained on vast amounts of text, so it can read and write language.","also":["LLM","LLMs"]},{"id":"genai","g":"ai","word":"Generative AI","text":"AI that creates new things, like text, pictures or code, rather than only sorting or spotting them.","also":["GenAI"]},{"id":"chatbot","g":"ai","word":"Chatbot","text":"A program you talk with in everyday language, by typing or speaking.","also":["chatbots"]},{"id":"prompt","g":"ai","word":"Prompt","text":"What you give an AI: your question or instructions, plus anything you hand it. Clearer prompts usually get better answers.","also":["prompts"]},{"id":"prompteng","g":"ai","word":"Prompt engineering","text":"The skill of writing prompts that get reliable, useful results."},{"id":"sysprompt","g":"ai","word":"System prompt","text":"Background instructions an AI gets before the conversation starts, setting its role and rules. They weigh more than what you type.","also":["system prompts","system instruction","system instructions"]},{"id":"context","g":"ai","word":"Context","text":"Everything the AI can see while it works: the instructions, your messages, files it has read and earlier replies.","noTip":1},{"id":"ctxwin","g":"ai","word":"Context window","text":"How much an AI can keep in mind at once, measured in tokens. Past that, older parts get dropped or summarised.","also":["context windows"]},{"id":"session","g":"ai","word":"Session","text":"One working conversation with an AI, from start to finish. A new session starts with a fresh memory.","also":["sessions"],"noTip":1},{"id":"memory","g":"ai","word":"Memory","text":"Notes an AI keeps between sessions, so it remembers your preferences and past decisions.","noTip":1},{"id":"hallucination","g":"ai","word":"Hallucination","text":"When an AI says something that sounds dead certain but is made up or wrong. Check the important facts.","also":["hallucinations","hallucinate","hallucinates"]},{"id":"training","g":"ai","word":"Training","text":"Teaching a model by showing it huge numbers of examples, before anyone uses it.","also":["trained"],"noTip":1},{"id":"trainingdata","g":"ai","word":"Training data","text":"The examples a model learned from. Its knowledge stops at the date that data was collected.","also":["training set"]},{"id":"cutoff","g":"ai","word":"Knowledge cutoff","text":"The date an AI’s built-in knowledge ends. It won’t know about later things unless it looks them up.","also":["training cutoff"]},{"id":"finetune","g":"ai","word":"Fine-tuning","text":"Extra training of an existing model on your own examples, to make it better at one particular job.","also":["fine-tune","fine-tuned","fine tuning"]},{"id":"inference","g":"ai","word":"Inference","text":"An AI model actually being used to answer something, as opposed to being trained.","also":["model inference"]},{"id":"tooluse","g":"ai","word":"Tool use","text":"An AI being able to do things, not just talk: run commands, read files or search the web, through tools the app gives it.","also":["tool calling","tool call","tool calls"]},{"id":"subagent","g":"ai","word":"Subagent","text":"A helper AI that a main AI hands a smaller job to, and gets the result back from.","also":["subagents","sub-agent"]},{"id":"multiagent","g":"ai","word":"Multi-agent","text":"Several AIs working together on one piece of work, each with its own part, like a small team.","also":["multi-agent system"]},{"id":"autonomy","g":"ai","word":"Autonomy","text":"How much an AI can do on its own before it has to ask a person.","also":["autonomous"]},{"id":"hitl","g":"ai","word":"Human in the loop","text":"Keeping a person involved to check or approve what the AI does at key points. In AI-gile that's you.","also":["human-in-the-loop","HITL"]},{"id":"guardrails","g":"ai","word":"Guardrails","text":"Limits and checks that keep an AI’s actions safe, like needing approval before anything goes live. They lower the risk of mistakes, but don’t rule them out.","also":["guardrail"]},{"id":"rag","g":"ai","word":"Retrieval-augmented generation (RAG)","text":"Letting an AI look things up in your own documents before it answers, so its answers rest on your facts.","also":["RAG","retrieval augmented generation"]},{"id":"embedding","g":"ai","word":"Embedding","text":"Turning text into a list of numbers that captures its meaning, so a computer can find things that mean similar things.","also":["embeddings"]},{"id":"vectordb","g":"ai","word":"Vector database","text":"A database built to search those lists of numbers (embeddings), to find material with a similar meaning.","also":["vector databases","vector store"]},{"id":"mcp","g":"ai","word":"Model Context Protocol (MCP)","text":"A common way to plug tools and data sources into AI apps, so an AI can use them.","also":["MCP"]},{"id":"temperature","g":"ai","word":"Temperature","text":"A setting for how adventurous an AI’s answers are. Low gives steadier, more predictable answers; high gives more varied ones. Neither makes it always right.","also":["model temperature"],"noTip":1},{"id":"multimodal","g":"ai","word":"Multimodal","text":"Able to work with more than one kind of information, such as text, pictures and sound.","also":["multi-modal"]},{"id":"evals","g":"ai","word":"Evaluation (eval)","text":"A planned test of how well an AI does on chosen examples, so you can compare models or prompts.","also":["eval","evals"]},{"id":"bias","g":"ai","word":"Bias","text":"When an AI (or a person) leans unfairly one way, often because of what it learned from.","also":["biased"],"noTip":1},{"id":"responsible","g":"ai","word":"Responsible AI","text":"Using AI fairly, safely and honestly, with people still answerable for the results.","also":["ethical AI"]},{"id":"injection","g":"ai","word":"Prompt injection","text":"A trick where hidden instructions in a web page or file try to make an AI do something its user didn’t ask for.","also":["prompt injections"]},{"id":"ratelimit","g":"ai","word":"Rate limit","text":"A cap on how many requests you can send to a service in a set time. Go over it and you have to wait.","also":["rate limits","rate limited"]},{"id":"usagelimit","g":"ai","word":"Usage limit","text":"How much AI work your plan allows in a period, after which it pauses or costs more.","also":["usage limits"]},{"id":"vibe","g":"ai","word":"Vibe coding","text":"Building software mostly by describing what you want to an AI and letting it write the code.","also":["vibe-coding"]},{"id":"budget","g":"money","word":"Budget","text":"The amount of money set aside for something.","also":["budgets"],"noTip":1},{"id":"costest","g":"money","word":"Cost estimate","text":"A best guess at what something will cost before you start.","also":["cost estimates"]},{"id":"roi","g":"money","word":"Return on investment (ROI)","text":"What you get back compared with what you put in. If it's positive, it was worth it.","also":["ROI"]},{"id":"tco","g":"money","word":"Total cost of ownership (TCO)","text":"Everything something really costs over its whole life, not just the price to buy it: running, support, upgrades and finally retiring it.","also":["TCO"]},{"id":"capex","g":"money","word":"CapEx and OpEx","text":"CapEx is money spent up front on things you keep; OpEx is ongoing spending, like monthly bills.","also":["CapEx","OpEx","capital expenditure","operating expenditure"]},{"id":"subscription","g":"money","word":"Subscription","text":"Paying regularly, usually monthly or yearly, to keep using something.","also":["subscriptions"],"noTip":1},{"id":"saas","g":"money","word":"Software as a service (SaaS)","text":"Software you use online and pay for by subscription, while the maker runs it for you.","also":["SaaS"]},{"id":"payg","g":"money","word":"Pay as you go","text":"Paying only for what you use, like cloud computing or AI tokens.","also":["pay-as-you-go","usage-based pricing"]},{"id":"overage","g":"money","word":"Overage","text":"Use above what your plan includes, which can cost extra.","also":["overages","overage charges"]},{"id":"billingalert","g":"money","word":"Billing alert","text":"A message when spending or use reaches a level you chose. It warns you, but doesn’t always stop further charges.","also":["billing alerts","spending alert"]},{"id":"freetier","g":"money","word":"Free tier","text":"A free level of a paid service, with limits. Handy for starting out.","also":["free plan"]},{"id":"pricing","g":"money","word":"Pricing plan","text":"The different packages a service sells, each with its own price and limits.","also":["pricing plans","price plan"]},{"id":"licence","g":"money","word":"Licence","text":"The rules for how you can use, copy, change or share something someone else made, such as software, fonts or pictures.","also":["licences","license","licenses"],"noTip":1},{"id":"opensource","g":"money","word":"Open source","text":"Software whose code anyone can read, use and often change for free, under the rules of its licence.","also":["open-source","open source software","OSS"]},{"id":"osslicence","g":"money","word":"Open source licence","text":"The rules that come with open source code. Some let you do almost anything (like MIT); some ask you to share your changes too (like GPL).","also":["open source licences","MIT licence","GPL"]},{"id":"proprietary","g":"money","word":"Proprietary","text":"Owned by a company and not free to copy or change. The opposite of open source.","also":["proprietary software"]},{"id":"copyright","g":"money","word":"Copyright","text":"The legal right of a creator to control copies of their work, including code and writing.","also":["copyrighted"],"noTip":1},{"id":"ip","g":"money","word":"Intellectual property (IP)","text":"Ideas and creations the law treats as owned, like code, designs, names and logos.","also":["intellectual property"]},{"id":"tos","g":"money","word":"Terms of service","text":"The rules you agree to when you use a service.","also":["terms and conditions","terms of use"]},{"id":"contract","g":"money","word":"Contract","text":"A written agreement between two sides that the law will back up.","also":["contracts"],"noTip":1},{"id":"sow","g":"money","word":"Statement of work (SOW)","text":"A document setting out exactly what work will be done, by when and for how much.","also":["SOW"]},{"id":"fixedprice","g":"money","word":"Fixed price","text":"An agreed price for the whole job, however long it takes.","also":["fixed-price"]},{"id":"tm","g":"money","word":"Time and materials","text":"Paying for the hours really worked and the things really used, rather than a set price.","also":["T&M"]},{"id":"invoice","g":"money","word":"Invoice","text":"A bill asking for payment for work done or goods supplied.","also":["invoices"],"noTip":1},{"id":"lockin","g":"money","word":"Vendor lock-in","text":"When moving away from a supplier is so hard or costly that you're stuck with them.","also":["lock-in"]},{"id":"procurement","g":"money","word":"Procurement","text":"The process of choosing and buying from suppliers."},{"id":"servicecredit","g":"money","word":"Service credit","text":"Money back or a discount you get when a supplier misses its SLA.","also":["service credits"]}]}};
